import type { H3Event } from 'h3'
import { CognitoIdentityProviderClient, InitiateAuthCommand } from '@aws-sdk/client-cognito-identity-provider'
import { sendEmail } from './brevo'

// Shared by server/api/otp.post.ts and server/api/invite.post.ts.
//
// The code is generated by the CreateAuthChallenge Lambda (lambda/src/
// custom-auth), not here — Cognito does not forward InitiateAuth's
// ClientMetadata to custom-auth trigger events for this pool (verified
// empirically), so pushing a server-chosen code into the Lambda doesn't
// work. Instead the Lambda exposes its code via publicChallengeParameters,
// which Cognito returns to this InitiateAuth call as `ChallengeParameters` —
// giving this function both the code AND the Session token from the same
// response, which is what it needs to build the one-click link embedding
// both. The code itself is never shown to the user — there's no UI to type
// it into (pages/verify-login-otp.vue is just a "check your email"
// message) — it only ever travels inside the link's query string.
export async function sendMagicLinkCode(event: H3Event, email: string): Promise<{ session?: string }> {
  const config = useRuntimeConfig()

  const client = new CognitoIdentityProviderClient({ region: config.public.cognitoRegion as string })
  const result = await client.send(new InitiateAuthCommand({
    AuthFlow: 'CUSTOM_AUTH',
    ClientId: config.public.cognitoClientId as string,
    AuthParameters: { USERNAME: email }
  }))

  const code = result.ChallengeParameters?.code
  if (!result.Session || !code) {
    // Previously a silent return: the user got no email and no error.
    console.error('[otp] CUSTOM_AUTH returned no Session/code; check the CreateAuthChallenge Lambda publicChallengeParameters', {
      challengeName: result.ChallengeName,
      hasSession: !!result.Session,
      paramKeys: Object.keys(result.ChallengeParameters || {})
    })
    throw createError({ statusCode: 502, statusMessage: 'Could not generate a sign-in link. Please try again.' })
  }

  // Prefer an explicit public site URL: behind CloudFront/ALB the request's
  // own host/protocol is often the internal one, which yields a dead link.
  let origin = (config.public.siteUrl as string | undefined)?.replace(/\/+$/, '')
  if (!origin) {
    origin = getRequestURL(event, { xForwardedHost: true, xForwardedProto: true }).origin
    const host = getHeader(event, 'host') || ''
    if (host.includes('localhost') || host.includes('127.0.0.1')) {
      origin = 'http://localhost:3000'
    }
  }

  const link = `${origin}/auth/callback?email=${encodeURIComponent(email)}&code=${encodeURIComponent(code)}&session=${encodeURIComponent(result.Session)}`

  await sendEmail({
    to: email,
    subject: 'Your Energystacks login link',
    html: `
      <p>Click below to sign in instantly:</p>
      <p><a href="${link}" style="display:inline-block;background:#000;color:#fff;padding:12px 24px;border-radius:8px;text-decoration:none;font-weight:bold;">Sign in to Energystacks</a></p>
      <p>This link expires in 10 minutes. If you didn't request this, you can ignore this email.</p>
    `
  })

  return { session: result.Session }
}
